command($content = @'
import sys
import json
import os
import datetime
import subprocess

BUDGET_FILE = r"C:\Users\ansac\.gemini\config\credit_budget.json"
LOG_FILE = r"C:\Users\ansac\.gemini\config\scripts\credit_guardian.log"

def log(msg):
    with open(LOG_FILE, "a") as f:
        f.write(f"[{datetime.datetime.now(datetime.timezone.utc).isoformat()}] {msg}\n")

def get_budget():
    if not os.path.exists(BUDGET_FILE):
        return {
            "max_tokens_per_5_hours": 2000000, 
            "usage_events": [],
            "conversations": {}
        }
    try:
        with open(BUDGET_FILE, "r") as f:
            return json.load(f)
    except:
        return {
            "max_tokens_per_5_hours": 2000000, 
            "usage_events": [],
            "conversations": {}
        }

def save_budget(budget):
    with open(BUDGET_FILE, "w") as f:
        json.dump(budget, f, indent=4)

def calculate_new_tokens(transcript_path):
    total = 0
    full_path = transcript_path.replace("transcript.jsonl", "transcript_full.jsonl")
    if not os.path.exists(full_path):
        return 500
    try:
        with open(full_path, "r", encoding="utf-8") as f:
            for line in f:
                try:
                    data = json.loads(line)
                    if data.get("type") == "PLANNER_RESPONSE":
                        usage = data.get("usage", {})
                        if isinstance(usage, dict):
                            total += usage.get("total_token_count", 0)
                except:
                    pass
    except Exception as e:
        log(f"Error reading transcript: {e}")
    return total

def main():
    try:
        payload_str = sys.stdin.read()
        if not payload_str.strip():
            print("{}")
            return

        payload = json.loads(payload_str)
        transcript_path = payload.get("transcriptPath", "")
        artifact_dir = payload.get("artifactDirectoryPath", "")
        conv_id = payload.get("conversationId", "unknown")

        budget = get_budget()
        if "max_tokens_per_5_hours" not in budget:
            budget["max_tokens_per_5_hours"] = budget.get("max_tokens_per_day", 2000000)
        if "usage_events" not in budget:
            budget["usage_events"] = []
        if "conversations" not in budget:
            budget["conversations"] = {}

        now = datetime.datetime.now(datetime.timezone.utc)
        five_hours_ago = now - datetime.timedelta(hours=5)

        valid_events = []
        for event in budget["usage_events"]:
            try:
                dt = datetime.datetime.fromisoformat(event["timestamp"])
                if dt > five_hours_ago:
                    valid_events.append(event)
            except:
                pass
        budget["usage_events"] = valid_events

        current_session_tokens = calculate_new_tokens(transcript_path)
        last_seen = budget["conversations"].get(conv_id, 0)
        delta = current_session_tokens - last_seen

        if delta < 0: delta = 500
        if delta == 0 and current_session_tokens == 0:
            delta = 200 

        budget["conversations"][conv_id] = current_session_tokens

        budget["usage_events"].append({
            "timestamp": now.isoformat(),
            "tokens": delta
        })

        current_usage = sum(e.get("tokens", 0) for e in budget["usage_events"])
        max_budget = budget.get("max_tokens_per_5_hours", 2000000)
        remaining = max_budget - current_usage
        percentage = remaining / max_budget

        log(f"Conv {conv_id} used {delta} tokens. Current 5hr Usage: {current_usage}. Remaining: {percentage:.1%}")
        save_budget(budget)

        if percentage <= 0.02:
            log("CRITICAL: Credit limit reached. Issuing termination.")
            oldest_dt = now
            if budget["usage_events"]:
                oldest_dt = datetime.datetime.fromisoformat(budget["usage_events"][0]["timestamp"])

            resume_dt = oldest_dt + datetime.timedelta(hours=5, minutes=1)
            if resume_dt <= now:
                resume_dt = now + datetime.timedelta(minutes=30)

            task_md_path = os.path.join(artifact_dir, "task.md")
            if os.path.exists(task_md_path):
                with open(task_md_path, "a") as f:
                    f.write(f"\n\n> [!CAUTION]\n> **SWARM PAUSED:** Rolling 5-hour limit reached. Awaiting next token chunk at {resume_dt.strftime('%H:%M UTC')}.\n")

            resume_local = resume_dt.astimezone()
            date_str = resume_local.strftime("%m/%d/%Y")
            time_str = resume_local.strftime("%H:%M")

            resume_cmd = f"schtasks /Create /F /TN AgentSwarmResume /TR \"echo Resume Swarm\" /SC ONCE /ST {time_str} /SD {date_str}"
            subprocess.run(resume_cmd, shell=True, capture_output=True)
            log(f"Scheduled resume for {time_str} on {date_str} local time.")

            response = {
                "terminationBehavior": "terminate",
                "injectSteps": [
                    {
                        "ephemeralMessage": f"CRITICAL: Global rolling token budget depleted (<= 2% remaining). Swarm forcefully terminated. Resume scheduled for {time_str}."
                    }
                ]
            }
            print(json.dumps(response))
        else:
            print("{}")

    except Exception as e:
        log(f"Fatal error in credit_guardian: {e}")
        print("{}")

if __name__ == "__main__":
    main()
'@
